<script setup lang="ts">
import AppLayout from '../../../layouts/AppLayout.vue';
import FormError from '../../../components/FormError.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

type Policy = { automatic_sanctions_enabled: boolean; yellow_card_threshold: number; yellow_suspension_matches: number; second_yellow_suspension_matches: number; red_card_suspension_matches: number };
type Simple = { id: number; name: string };
type Competition = Simple & { tournament: { season: Simple } };
type Match = { id: number; scheduled_at: string | null; matchday: Simple; home_participation: { registered_name: string }; away_participation: { registered_name: string } };
type Appeal = { id: number; status: string; statement: string; submitted_at: string; resolution: string | null; has_evidence: boolean; appellant: { name: string }; reviewer: { name: string } | null };
type Sanction = { id: number; subject_type: string; subject_name: string; kind: string; source: string; reason: string; legal_basis: string | null; matches_total: number; matches_served: number; points_deducted: number; fine_amount: string | null; status: string; issued_at: string; appeal_deadline_at: string; completed_at: string | null; team: Simple | null; season: Simple | null; competition: Simple | null; match: { id: number; matchday: Simple | null } | null; appeal: Appeal | null; can_appeal: boolean; can_resolve: boolean };
type Pagination = { data: Sanction[]; links: { url: string | null; label: string; active: boolean }[]; from: number | null; to: number | null; total: number };

const props = defineProps<{ policy: Policy; sanctions: Pagination; permissions: { manage: boolean; appeal: boolean }; players: { id: number; full_name: string }[]; teams: Simple[]; seasons: Simple[]; competitions: Competition[]; matches: Match[] }>();
const policyOpen = ref(false);
const sanctionOpen = ref(false);
const appealTarget = ref<Sanction | null>(null);
const resolveTarget = ref<Sanction | null>(null);
const syncing = ref(false);

const policyForm = useForm({ ...props.policy, reason: '' });
const sanctionForm = useForm({ subject_type: 'player', player_id: null as number | null, team_id: null as number | null, subject_name: '', kind: 'suspension', season_id: null as number | null, competition_id: null as number | null, match_id: null as number | null, matches_total: 1, points_deducted: 1, fine_amount: null as number | null, reason: '', legal_basis: '' });
const appealForm = useForm({ statement: '', evidence: null as File | null });
const resolveForm = useForm({ action: 'uphold', matches_total: 0, points_deducted: 0, fine_amount: 0, resolution: '' });

const subjectLabels: Record<string, string> = { player: 'Jugador', team: 'Equipo', staff: 'Cuerpo técnico' };
const kindLabels: Record<string, string> = { suspension: 'Suspensión', points_deduction: 'Descuento de puntos', fine: 'Multa', warning: 'Amonestación administrativa', disqualification: 'Descalificación' };
const statusLabels: Record<string, string> = { active: 'Vigente', completed: 'Cumplida', revoked: 'Revocada' };
const appealLabels: Record<string, string> = { submitted: 'En revisión', upheld: 'Confirmada', reduced: 'Reducida', revoked: 'Revocada' };
const activeCount = computed(() => props.sanctions.data.filter((item) => item.status === 'active').length);
const pendingAppeals = computed(() => props.sanctions.data.filter((item) => item.appeal?.status === 'submitted').length);

function dateTime(value: string | null): string { return value ? new Intl.DateTimeFormat('es-MX', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'; }
function money(value: string | null): string { return value ? new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(Number(value)) : '—'; }
function policySubmit(): void { policyForm.put('/liga/disciplina/configuracion', { preserveScroll: true, onSuccess: () => { policyOpen.value = false; policyForm.reason = ''; } }); }
function sanctionSubmit(): void { sanctionForm.post('/liga/sanciones', { preserveScroll: true, onSuccess: () => { sanctionOpen.value = false; sanctionForm.reset(); sanctionForm.subject_type = 'player'; sanctionForm.kind = 'suspension'; sanctionForm.matches_total = 1; sanctionForm.points_deducted = 1; } }); }
function syncReports(): void { syncing.value = true; router.post('/liga/sanciones/sincronizar', {}, { preserveScroll: true, onFinish: () => { syncing.value = false; } }); }
function openAppeal(item: Sanction): void { appealTarget.value = item; appealForm.reset(); appealForm.clearErrors(); }
function appealSubmit(): void { if (!appealTarget.value) return; appealForm.post(`/liga/sanciones/${appealTarget.value.id}/apelaciones`, { forceFormData: true, preserveScroll: true, onSuccess: () => { appealTarget.value = null; appealForm.reset(); } }); }
function openResolve(item: Sanction): void { resolveTarget.value = item; resolveForm.reset(); resolveForm.clearErrors(); resolveForm.action = 'uphold'; resolveForm.matches_total = item.matches_total; resolveForm.points_deducted = item.points_deducted; resolveForm.fine_amount = Number(item.fine_amount ?? 0); }
function resolveSubmit(): void { if (!resolveTarget.value?.appeal) return; resolveForm.post(`/liga/apelaciones/${resolveTarget.value.appeal.id}/resolver`, { preserveScroll: true, onSuccess: () => { resolveTarget.value = null; resolveForm.reset(); } }); }
</script>

<template>
    <Head title="Sanciones y disciplina" />
    <AppLayout>
        <section>
            <div class="flex flex-col justify-between gap-4 lg:flex-row lg:items-start">
                <div><p class="text-sm font-semibold uppercase tracking-[0.18em] text-league-600">Módulo 14</p><h1 class="mt-1 text-3xl font-semibold">Sanciones y apelaciones</h1><p class="mt-2 max-w-3xl text-slate-600">Control de suspensiones, sanciones administrativas, cumplimiento por partidos oficiales y apelaciones.</p></div>
                <div v-if="permissions.manage" class="flex flex-wrap gap-2"><button class="btn-secondary" type="button" :disabled="syncing" @click="syncReports">{{ syncing ? 'Sincronizando…' : 'Sincronizar cédulas' }}</button><button class="btn-secondary" type="button" @click="policyOpen = true">Configuración</button><button class="btn-primary" type="button" @click="sanctionOpen = true">Nueva sanción</button></div>
            </div>

            <div class="mt-6 grid gap-4 sm:grid-cols-3"><div class="stat-card"><span class="stat-label">Sanciones mostradas</span><span class="stat-value">{{ sanctions.total }}</span></div><div class="stat-card"><span class="stat-label">Vigentes en esta página</span><span class="stat-value">{{ activeCount }}</span></div><div class="stat-card"><span class="stat-label">Apelaciones pendientes</span><span class="stat-value">{{ pendingAppeals }}</span></div></div>

            <div v-if="!sanctions.data.length" class="card mt-6 p-12 text-center text-slate-600">No existen sanciones visibles para este acceso.</div>
            <div v-else class="mt-6 space-y-4">
                <article v-for="item in sanctions.data" :key="item.id" class="card overflow-hidden">
                    <header class="flex flex-col justify-between gap-3 border-b border-slate-200 p-5 md:flex-row md:items-start">
                        <div><div class="flex flex-wrap items-center gap-2"><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold">{{ subjectLabels[item.subject_type] }}</span><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="item.status === 'active' ? 'bg-red-100 text-red-800' : item.status === 'completed' ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-200 text-slate-700'">{{ statusLabels[item.status] }}</span><span class="text-xs font-semibold uppercase text-slate-500">{{ item.source === 'automatic' ? 'Automática' : 'Manual' }}</span></div><h2 class="mt-2 text-xl font-semibold">{{ item.subject_name }}</h2><p class="mt-1 text-sm text-slate-500">{{ kindLabels[item.kind] }} · Emitida {{ dateTime(item.issued_at) }}</p></div>
                        <div class="flex gap-2"><button v-if="item.can_appeal" class="btn-secondary" type="button" @click="openAppeal(item)">Presentar apelación</button><button v-if="item.can_resolve" class="btn-primary" type="button" @click="openResolve(item)">Resolver apelación</button></div>
                    </header>
                    <div class="grid gap-5 p-5 lg:grid-cols-[1fr_280px]"><div><h3 class="text-sm font-semibold uppercase text-slate-500">Motivo</h3><p class="mt-1 whitespace-pre-line text-sm text-slate-800">{{ item.reason }}</p><div v-if="item.legal_basis" class="mt-4"><h3 class="text-sm font-semibold uppercase text-slate-500">Fundamento</h3><p class="mt-1 whitespace-pre-line text-sm">{{ item.legal_basis }}</p></div><div class="mt-4 flex flex-wrap gap-x-5 gap-y-2 text-sm text-slate-600"><span v-if="item.team">Equipo: <strong>{{ item.team.name }}</strong></span><span v-if="item.season">Temporada: <strong>{{ item.season.name }}</strong></span><span v-if="item.competition">Competencia: <strong>{{ item.competition.name }}</strong></span><span v-if="item.match">Partido relacionado: <strong>{{ item.match.matchday?.name ?? `#${item.match.id}` }}</strong></span></div></div><aside class="rounded-xl bg-slate-50 p-4 text-sm"><template v-if="item.kind === 'suspension'"><p class="text-slate-500">Partidos cumplidos</p><p class="mt-1 text-2xl font-bold">{{ item.matches_served }} / {{ item.matches_total }}</p><div class="mt-2 h-2 overflow-hidden rounded bg-slate-200"><div class="h-full bg-league-600" :style="{ width: `${Math.min(100, item.matches_total ? item.matches_served / item.matches_total * 100 : 100)}%` }"></div></div></template><p v-else-if="item.kind === 'points_deduction'"><span class="text-slate-500">Puntos descontados</span><strong class="mt-1 block text-2xl text-red-700">-{{ item.points_deducted }}</strong></p><p v-else-if="item.kind === 'fine'"><span class="text-slate-500">Importe</span><strong class="mt-1 block text-xl">{{ money(item.fine_amount) }}</strong></p><p class="mt-4 text-xs text-slate-500">Plazo de apelación:<br><strong>{{ dateTime(item.appeal_deadline_at) }}</strong></p></aside></div>
                    <div v-if="item.appeal" class="border-t border-amber-200 bg-amber-50 p-5"><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="font-semibold">Apelación · {{ appealLabels[item.appeal.status] }}</h3><a v-if="item.appeal.has_evidence" :href="`/liga/apelaciones/${item.appeal.id}/evidencia`" class="text-sm font-semibold text-league-700 underline">Descargar evidencia</a></div><p class="mt-2 whitespace-pre-line text-sm">{{ item.appeal.statement }}</p><p class="mt-2 text-xs text-slate-500">Presentada por {{ item.appeal.appellant.name }} · {{ dateTime(item.appeal.submitted_at) }}</p><div v-if="item.appeal.resolution" class="mt-3 rounded-lg bg-white p-3 text-sm"><strong>Resolución:</strong> {{ item.appeal.resolution }}</div></div>
                </article>
            </div>
            <nav v-if="sanctions.links.length > 3" class="mt-6 flex flex-wrap justify-center gap-1"><Link v-for="link in sanctions.links" :key="link.label" :href="link.url ?? '#'" class="rounded-lg border px-3 py-2 text-sm" :class="[link.active ? 'border-league-600 bg-league-600 text-white' : 'border-slate-200 bg-white', !link.url ? 'pointer-events-none opacity-40' : '']" preserve-scroll><span v-html="link.label"></span></Link></nav>
        </section>

        <div v-if="policyOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4" @click.self="policyOpen = false"><form class="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6" @submit.prevent="policySubmit"><h2 class="text-xl font-semibold">Configuración disciplinaria</h2><p class="mt-1 text-sm text-slate-500">Los valores son propios de esta liga y solo afectan sanciones nuevas.</p><label class="mt-5 flex items-center gap-3 rounded-xl border p-4"><input v-model="policyForm.automatic_sanctions_enabled" type="checkbox"><span><strong>Generar sanciones automáticas</strong><small class="block text-slate-500">Desde tarjetas de cédulas aprobadas.</small></span></label><div class="mt-4 grid gap-4 sm:grid-cols-2"><div><label class="form-label">Amarillas para suspensión</label><input v-model.number="policyForm.yellow_card_threshold" class="form-input" type="number" min="1" max="20"><FormError :message="policyForm.errors.yellow_card_threshold" /></div><div><label class="form-label">Partidos por acumulación</label><input v-model.number="policyForm.yellow_suspension_matches" class="form-input" type="number" min="1" max="20"></div><div><label class="form-label">Partidos por segunda amarilla</label><input v-model.number="policyForm.second_yellow_suspension_matches" class="form-input" type="number" min="1" max="20"></div><div><label class="form-label">Partidos por roja directa</label><input v-model.number="policyForm.red_card_suspension_matches" class="form-input" type="number" min="1" max="50"></div></div><div class="mt-4"><label class="form-label">Motivo del cambio</label><textarea v-model="policyForm.reason" class="form-input" required maxlength="500"></textarea><FormError :message="policyForm.errors.reason" /></div><div class="mt-6 flex justify-end gap-2"><button class="btn-secondary" type="button" @click="policyOpen = false">Cancelar</button><button class="btn-primary" :disabled="policyForm.processing">Guardar configuración</button></div></form></div>

        <div v-if="sanctionOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4" @click.self="sanctionOpen = false"><form class="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white p-6" @submit.prevent="sanctionSubmit"><h2 class="text-xl font-semibold">Registrar sanción manual</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><div><label class="form-label">Sancionado</label><select v-model="sanctionForm.subject_type" class="form-input"><option value="player">Jugador</option><option value="team">Equipo</option><option value="staff">Cuerpo técnico</option></select></div><div><label class="form-label">Tipo de sanción</label><select v-model="sanctionForm.kind" class="form-input"><option value="suspension">Suspensión</option><option value="points_deduction">Descuento de puntos</option><option value="fine">Multa</option><option value="warning">Amonestación administrativa</option><option value="disqualification">Descalificación</option></select></div><div v-if="sanctionForm.subject_type === 'player'"><label class="form-label">Jugador</label><select v-model="sanctionForm.player_id" class="form-input" required><option :value="null" disabled>Selecciona</option><option v-for="player in players" :key="player.id" :value="player.id">{{ player.full_name }}</option></select><FormError :message="sanctionForm.errors.player_id" /></div><div v-if="sanctionForm.subject_type !== 'player'"><label class="form-label">Equipo</label><select v-model="sanctionForm.team_id" class="form-input" required><option :value="null" disabled>Selecciona</option><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select><FormError :message="sanctionForm.errors.team_id" /></div><div v-if="sanctionForm.subject_type === 'staff'"><label class="form-label">Nombre del integrante</label><input v-model="sanctionForm.subject_name" class="form-input" required maxlength="180"><FormError :message="sanctionForm.errors.subject_name" /></div><div><label class="form-label">Temporada</label><select v-model="sanctionForm.season_id" class="form-input"><option :value="null">Sin limitar</option><option v-for="season in seasons" :key="season.id" :value="season.id">{{ season.name }}</option></select></div><div><label class="form-label">Competencia</label><select v-model="sanctionForm.competition_id" class="form-input" :required="sanctionForm.kind === 'points_deduction'"><option :value="null">Sin limitar</option><option v-for="competition in competitions" :key="competition.id" :value="competition.id">{{ competition.tournament.season.name }} · {{ competition.name }}</option></select><FormError :message="sanctionForm.errors.competition_id" /></div><div class="sm:col-span-2"><label class="form-label">Partido relacionado (opcional)</label><select v-model="sanctionForm.match_id" class="form-input"><option :value="null">Sin partido</option><option v-for="match in matches" :key="match.id" :value="match.id">{{ match.matchday?.name }} · {{ match.home_participation.registered_name }} vs {{ match.away_participation.registered_name }}</option></select></div><div v-if="sanctionForm.kind === 'suspension'"><label class="form-label">Partidos de suspensión</label><input v-model.number="sanctionForm.matches_total" class="form-input" type="number" min="1" max="100" required></div><div v-if="sanctionForm.kind === 'points_deduction'"><label class="form-label">Puntos a descontar</label><input v-model.number="sanctionForm.points_deducted" class="form-input" type="number" min="1" max="100" required></div><div v-if="sanctionForm.kind === 'fine'"><label class="form-label">Importe de multa</label><input v-model.number="sanctionForm.fine_amount" class="form-input" type="number" min="0.01" step="0.01" required></div><div class="sm:col-span-2"><label class="form-label">Motivo</label><textarea v-model="sanctionForm.reason" class="form-input" required maxlength="3000"></textarea><FormError :message="sanctionForm.errors.reason" /></div><div class="sm:col-span-2"><label class="form-label">Fundamento reglamentario</label><textarea v-model="sanctionForm.legal_basis" class="form-input" maxlength="3000"></textarea></div></div><div class="mt-6 flex justify-end gap-2"><button class="btn-secondary" type="button" @click="sanctionOpen = false">Cancelar</button><button class="btn-primary" :disabled="sanctionForm.processing">Registrar sanción</button></div></form></div>

        <div v-if="appealTarget" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4" @click.self="appealTarget = null"><form class="w-full max-w-xl rounded-2xl bg-white p-6" @submit.prevent="appealSubmit"><h2 class="text-xl font-semibold">Apelar sanción</h2><p class="mt-1 text-sm text-slate-500">{{ appealTarget.subject_name }} · vence {{ dateTime(appealTarget.appeal_deadline_at) }}</p><div class="mt-5"><label class="form-label">Argumentos de la apelación</label><textarea v-model="appealForm.statement" class="form-input min-h-36" required minlength="20" maxlength="5000"></textarea><FormError :message="appealForm.errors.statement" /></div><div class="mt-4"><label class="form-label">Evidencia opcional</label><input class="form-input" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" @change="appealForm.evidence = ($event.target as HTMLInputElement).files?.[0] ?? null"><p class="mt-1 text-xs text-slate-500">PDF o imagen, máximo 5 MB.</p><FormError :message="appealForm.errors.evidence" /></div><div class="mt-6 flex justify-end gap-2"><button class="btn-secondary" type="button" @click="appealTarget = null">Cancelar</button><button class="btn-primary" :disabled="appealForm.processing">Enviar apelación</button></div></form></div>

        <div v-if="resolveTarget" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4" @click.self="resolveTarget = null"><form class="w-full max-w-xl rounded-2xl bg-white p-6" @submit.prevent="resolveSubmit"><h2 class="text-xl font-semibold">Resolver apelación</h2><p class="mt-1 text-sm text-slate-500">{{ resolveTarget.subject_name }}</p><div class="mt-5"><label class="form-label">Resolución</label><select v-model="resolveForm.action" class="form-input"><option value="uphold">Confirmar sanción</option><option v-if="['suspension', 'points_deduction', 'fine'].includes(resolveTarget.kind)" value="reduce">Reducir sanción</option><option value="revoke">Revocar sanción</option></select></div><div v-if="resolveForm.action === 'reduce' && resolveTarget.kind === 'suspension'" class="mt-4"><label class="form-label">Nueva duración en partidos</label><input v-model.number="resolveForm.matches_total" class="form-input" type="number" min="0" :max="Math.max(0, resolveTarget.matches_total - 1)"><FormError :message="resolveForm.errors.matches_total" /></div><div v-if="resolveForm.action === 'reduce' && resolveTarget.kind === 'points_deduction'" class="mt-4"><label class="form-label">Nuevo descuento de puntos</label><input v-model.number="resolveForm.points_deducted" class="form-input" type="number" min="0" :max="Math.max(0, resolveTarget.points_deducted - 1)"><FormError :message="resolveForm.errors.points_deducted" /></div><div v-if="resolveForm.action === 'reduce' && resolveTarget.kind === 'fine'" class="mt-4"><label class="form-label">Nuevo importe</label><input v-model.number="resolveForm.fine_amount" class="form-input" type="number" min="0.01" :max="Math.max(0, Number(resolveTarget.fine_amount ?? 0) - 0.01)" step="0.01"><FormError :message="resolveForm.errors.fine_amount" /></div><div class="mt-4"><label class="form-label">Fundamento de la resolución</label><textarea v-model="resolveForm.resolution" class="form-input min-h-28" required minlength="10" maxlength="5000"></textarea><FormError :message="resolveForm.errors.resolution" /></div><div class="mt-6 flex justify-end gap-2"><button class="btn-secondary" type="button" @click="resolveTarget = null">Cancelar</button><button class="btn-primary" :disabled="resolveForm.processing">Guardar resolución</button></div></form></div>
    </AppLayout>
</template>
